import { MeshStandardNodeMaterial, Group, Mesh, PlaneGeometry, DoubleSide, Texture } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  uniform,
  mix,
  smoothstep,
  abs,
  max,
  length,
  clamp,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'badge-collection';

  // --- Geometry: capsule badge plane ---
  const width = 1.6;
  const height = 0.46;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // --- TSL uniforms ---
  const uHover = uniform(0.0);
  const uPress = uniform(0.0);

  // Placeholder texture until async load resolves.
  const placeholderTex = new Texture();
  const texNode = texture(placeholderTex, uv());

  // Capsule SDF in local plane-unit space.
  const halfSize = vec2(width * 0.5, height * 0.5);
  const radius = float(height * 0.5);
  const p = uv().sub(vec2(0.5, 0.5)).mul(vec2(width, height));
  const dx = max(abs(p.x).sub(halfSize.x.sub(radius)), float(0.0));
  const dist = length(vec2(dx, p.y)).sub(radius);

  // Inside mask (soft anti-aliased edge).
  const aa = float(0.01);
  const insideMask = smoothstep(aa, aa.negate(), dist);

  // Edge glow band just inside the capsule border, brighter on hover/focus.
  const edgeBand = smoothstep(float(0.05), float(0.0), abs(dist));
  const edgeIntensity = uHover.mul(0.9).add(0.35);
  const accentColor = vec3(
    parseInt(colors.accent.slice(1, 3), 16) / 255,
    parseInt(colors.accent.slice(3, 5), 16) / 255,
    parseInt(colors.accent.slice(5, 7), 16) / 255
  );
  const inkColor = vec3(
    parseInt(colors.ink.slice(1, 3), 16) / 255,
    parseInt(colors.ink.slice(3, 5), 16) / 255,
    parseInt(colors.ink.slice(5, 7), 16) / 255
  );
  const surfaceColor = vec3(
    parseInt(colors.surface.slice(1, 3), 16) / 255,
    parseInt(colors.surface.slice(3, 5), 16) / 255,
    parseInt(colors.surface.slice(5, 7), 16) / 255
  );

  // Base fill: ink/surface blend, grain texture multiplied in for machined feel.
  const baseFill = mix(surfaceColor, inkColor, float(0.5)).mul(
    mix(vec3(0.85, 0.85, 0.85), vec3(1.0, 1.0, 1.0), texNode.r)
  );

  const colorNode = mix(baseFill, accentColor, edgeBand.mul(0.5));
  const emissiveNode = accentColor.mul(edgeBand).mul(edgeIntensity).mul(clamp(uPress.add(1.0), 0.0, 1.6));
  const opacityNode = insideMask;

  const material = new MeshStandardNodeMaterial();
  material.transparent = true;
  material.side = DoubleSide;
  material.roughness = 0.62;
  material.metalness = 0.4;
  material.clearcoat = 0.18;
  material.colorNode = colorNode;
  material.opacityNode = opacityNode;
  material.emissiveNode = emissiveNode;

  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 5;
  group.add(mesh);

  // --- Async texture load (ceramic grain) ---
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        texNode.value = tex;
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  // --- Primitives (none configured, but applied generically per contract) ---
  const appliedPrimitives = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const result = fn(group, prim.params ?? {});
      if (result) appliedPrimitives.push(result);
    }
  }

  // --- Motion state ---
  const baseY = 0;
  const liftAmount = 0.15;
  let hoverTl = null;
  let pressTl = null;

  const onHoverStart = () => {
    uHover.value = 1.0;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, { y: baseY + liftAmount, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(mesh.rotation, { x: -0.07, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(mesh.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.9, ease: 'power4.out' }, 0);
  };

  const onHoverEnd = () => {
    uHover.value = 0.0;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, { y: baseY, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(mesh.rotation, { x: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(mesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.6, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    uPress.value = 1.0;
    pressTl = gsap.timeline({
      onComplete: () => {
        uPress.value = 0.0;
      },
    });
    pressTl.to(mesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(mesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.25, ease: 'power2.out' });
    ctx.emit('hub-collection.select', { source: 'badge-collection' });
  };

  group.userData.handlers = {
    hover: (isHovering) => {
      if (isHovering) onHoverStart();
      else onHoverEnd();
    },
    click: onClick,
    onPointerOver: onHoverStart,
    onPointerOut: onHoverEnd,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    for (const p of appliedPrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    geometry.dispose();
    material.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
    placeholderTex.dispose();
  };

  return group;
}
